import math, itertools, random, bisect, heapq
from collections import Counter, deque, defaultdict
from functools import lru_cache

def partitions(text):
    s = text.strip()
    last = {c: i for (i, c) in enumerate(s)}
    end = 0
    start = 0
    out = []
    for (i, c) in enumerate(s):
        end = max(end, last[c])
        if i == end:
            out.append(i - start + 1)
            start = i + 1
    return ' '.join(map(str, out))
import sys
sys.stdout.write(partitions(sys.stdin.read()) + '\n')

import math, itertools, random, bisect, heapq
from collections import Counter, deque, defaultdict
from functools import lru_cache

def redundant(text):
    v = list(map(int, text.split()))
    n = v[0]
    parent = list(range(n + 1))
    answer = None

    def root(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for (u, w) in zip(v[1::2], v[2::2]):
        (a, b) = (root(u), root(w))
        if a == b:
            answer = (u, w)
        else:
            parent[a] = b
    return ' '.join(map(str, answer))
