def tag_valid(text):
    s = text.rstrip('\r\n')
    i = 0
    stack = []
    while i < len(s):
        if i > 0 and (not stack):
            return 'false'
        if s.startswith('<![CDATA[', i):
            if not stack:
                return 'false'
            end = s.find(']]>', i + 9)
            if end < 0:
                return 'false'
            i = end + 3
        elif s[i] == '<':
            end = s.find('>', i + 1)
            if end < 0:
                return 'false'
            closing = s.startswith('</', i)
            name = s[i + 2:end] if closing else s[i + 1:end]
            if not (1 <= len(name) <= 9 and all(('A' <= c <= 'Z' for c in name))):
                return 'false'
            if closing:
                if not stack or stack.pop() != name:
                    return 'false'
            else:
                stack.append(name)
            i = end + 1
        else:
            if not stack:
                return 'false'
            i += 1
    return 'true' if not stack and s.startswith('<') and (len(s) > 0) else 'false'
import sys
