import math, itertools, random, bisect, heapq
from collections import Counter, deque, defaultdict
from functools import lru_cache

def frequency_windows(text):
    v = list(map(int, text.split()))
    (n, w, k) = v[:3]
    a = v[3:]
    counts = Counter()
    eligible = []
    out = []
    for (i, x) in enumerate(a):
        counts[x] += 1
        if counts[x] == k:
            heapq.heappush(eligible, x)
        if i >= w:
            counts[a[i - w]] -= 1
        if i >= w - 1:
            while eligible and counts[eligible[0]] < k:
                heapq.heappop(eligible)
            out.append(eligible[0] if eligible else -1)
    return ' '.join(map(str, out))
