def energy_jumps(text):
    v = list(map(int, text.split()))
    n = v[0]
    a = v[1:]
    bound = max(a)
    spf = list(range(bound + 1))
    for p in range(2, math.isqrt(bound) + 1):
        if spf[p] == p:
            for j in range(p * p, bound + 1, p):
                if spf[j] == j:
                    spf[j] = p
    dp = [n] * n
    dp[0] = 0
    for (i, value) in enumerate(a):
        if i + 1 < n:
            dp[i + 1] = min(dp[i + 1], dp[i] + 1)
        while value > 1:
            p = spf[value]
            if i + p < n:
                dp[i + p] = min(dp[i + p], dp[i] + 1)
            while value % p == 0:
                value //= p
    return str(dp[-1])
