def balanced(text):
    v = list(map(int, text.split()))
    n = v[0]
    a = v[1:]
    half = n // 2

    def grouped(row):
        groups = [[] for i in range(len(row) + 1)]
        groups[0] = [0]
        for (at, x) in enumerate(row):
            for count in range(at + 1, 0, -1):
                groups[count].extend((s + x for s in groups[count - 1]))
        return groups
    left = grouped(a[:half])
    right = grouped(a[half:])
    total = sum(a)
    best = total
    for (count, row) in enumerate(left):
        other = sorted(right[half - count])
        for x in row:
            at = bisect.bisect_left(other, (total - 2 * x + 1) // 2)
            for j in (at - 1, at):
                if 0 <= j < len(other):
                    best = min(best, abs(total - 2 * (x + other[j])))
    return str(best)
import sys
