def homework_time(text):
    v = list(map(int, text.split()))
    (n, m, score) = v[:3]
    a = v[3:]
    if score == 0:
        return '0'

    def count(limit):
        return sum((min(m, (limit // k + 1) // 2) for k in a))
    (low, high) = (1, max(a) * (2 * m - 1))
    while low < high:
        middle = (low + high) // 2
        if count(middle) >= score:
            high = middle
        else:
            low = middle + 1
    cutoff = low
    answer = 0
    selected = 0
    for k in a:
        c = min(m, ((cutoff - 1) // k + 1) // 2)
        selected += c
        answer += k * c * c
    return str(answer + (score - selected) * cutoff)
