import math, itertools, random, bisect, heapq, ast, datetime
from collections import Counter, deque, defaultdict
from functools import lru_cache

def matrix(text):
    value = ast.literal_eval(text.strip())
    if isinstance(value, tuple):
        return [list(row) for row in value]
    if isinstance(value, list) and (not value or isinstance(value[0], (list, tuple))):
        return value
    raise ValueError('要求二维数组')

def word_game(text):
    words = text.split()[1:]
    children = [{}]
    terminal = [False]
    for word in words:
        u = 0
        for c in word:
            if c not in children[u]:
                children[u][c] = len(children)
                children.append({})
                terminal.append(False)
            u = children[u][c]
        terminal[u] = True
    win = [False] * len(children)
    for u in range(len(children) - 1, -1, -1):
        win[u] = any((terminal[w] or not win[w] for w in children[u].values()))
    return 'Alice' if win[0] else 'Bob'

def words(text):
    rows = text.splitlines()
    board = matrix(rows[0])
    items = ast.literal_eval(rows[1])
    items = [items] if isinstance(items, str) else list(items)
    trie = {}
    for word in items:
        current = trie
        for c in word:
            current = current.setdefault(c, {})
        current['#'] = word
    (h, w) = (len(board), len(board[0]))
    found = set()
    seen = set()

    def visit(r, c, node):
        character = board[r][c]
        if character not in node:
            return
        child = node[character]
        if '#' in child:
            found.add(child['#'])
        seen.add((r, c))
        for (dr, dc) in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            (a, b) = (r + dr, c + dc)
            if 0 <= a < h and 0 <= b < w and ((a, b) not in seen):
                visit(a, b, child)
        seen.remove((r, c))
    for r in range(h):
        for c in range(w):
            visit(r, c, trie)
    return ','.join(sorted(found))
import sys
sys.stdout.write(word_game(sys.stdin.read()) + '\n')

