def identity(text):
    t = text.split()
    weights = [7, 9, 10, 5, 8, 4, 2, 1, 6, 3, 7, 9, 10, 5, 8, 4, 2]
    codes = '10X98765432'
    out = []
    for mask in t[1:]:
        at = mask.index('?')
        valid = []
        for c in '0123456789X' if at == 17 else '0123456789':
            number = mask[:at] + c + mask[at + 1:]
            if number[0] == '0':
                continue
            try:
                year = int(number[6:10])
                datetime.date(year, int(number[10:12]), int(number[12:14]))
            except ValueError:
                continue
            if not 1800 <= year <= 2099:
                continue
            checksum = codes[sum((int(x) * w for (x, w) in zip(number[:17], weights))) % 11]
            if checksum == number[17]:
                valid.append(number)
        out.append(valid[0] if len(valid) == 1 else 'UNCERTAIN' if valid else 'IMPOSSIBLE')
    return '\n'.join(out)
