def police(text):
    v = list(map(int, text.split()))
    (n, k) = v[:2]
    groups = deque()
    answer = 0
    for (minute, event) in enumerate(v[2:], 1):
        while groups and groups[0][0] < minute:
            groups.popleft()
        if event > 0:
            groups.append([minute + k - 1, event])
        elif groups:
            groups[0][1] -= 1
            if groups[0][1] == 0:
                groups.popleft()
        else:
            answer += 1
    return str(answer)
