    raise ValueError('要求二维数组')

def network(text):
    rows = text.splitlines()
    edges = matrix(rows[0])
    (n, k) = map(int, rows[1:3])
    g = [[] for i in range(n)]
    for (u, w, c) in edges:
        g[u - 1].append((w - 1, c))
    distance = [10 ** 100] * n
    distance[k - 1] = 0
    q = [(0, k - 1)]
    while q:
        (d, u) = heapq.heappop(q)
        if d != distance[u]:
            continue
        for (w, c) in g[u]:
            if d + c < distance[w]:
                distance[w] = d + c
                heapq.heappush(q, (d + c, w))
    return str(max(distance) if max(distance) < 10 ** 100 else -1)
import sys
