def lyrics(text):
    t = text.split()
    n = int(t[0])
    words = t[1:]
    size = 1 << n
    dp = [0] * size
    dp[0] = (1 << 26) - 1
    count = [0] * size
    answer = 0
    for mask in range(size):
        if mask:
            count[mask] = count[mask >> 1] + (mask & 1)
        if not dp[mask]:
            continue
        answer = max(answer, count[mask])
        for (i, word) in enumerate(words):
            if not mask >> i & 1 and dp[mask] >> ord(word[0]) - 97 & 1:
                dp[mask | 1 << i] |= 1 << ord(word[-1]) - 97
    return str(answer)
