def conventional_undo(text):
 nodes=[(None,None,0)];state=0;history=[];out=[]
 for line in text.splitlines()[1:]:
  row=line.split();op=row[0]
  if op=='max':out.append(str(nodes[state][1]) if state else 'None')
  elif op=='push':
   value=int(row[1]);history.append(state);nodes.append((value,max(value,nodes[state][1]) if state else value,state));state=len(nodes)-1
  elif op=='pop':
   if state:history.append(state);state=nodes[state][2]
  elif op=='undo':
   if history:state=history.pop()
 return '\n'.join(out)

